import sys


def main():
    data = sys.stdin.read().split()
    n, k, lo, hi = map(int, data[:4])
    a = list(map(int, data[4:4 + n]))
    count = 0
    for mask in range(1 << n):
        if bin(mask).count('1') != k:
            continue
        s = 0
        for i in range(n):
            if (mask >> i) & 1:
                s += a[i]
        if lo <= s <= hi:
            count += 1
    print(count)


main()
